#include <stdio.h>

int main(void) {
    int a[] = {5, 2, 8, 1, 3}, n = 5;
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
    for (int i = 0; i < n; i++) printf("%d%s", a[i], i == n - 1 ? "\n" : " ");
    int lo = 0, hi = n - 1, key = 3, idx = -1;
    while (lo <= hi) {
        int m = (lo + hi) / 2;
        if (a[m] == key) { idx = m; break; }
        if (a[m] < key) lo = m + 1; else hi = m - 1;
    }
    printf("found=%d\n", idx);
    return 0;
}

